def firstIndexRotated(nums, target):
    n = len(nums)
    lo, hi = 0, n - 1
    s = None
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] > nums[hi]:
            lo = mid + 1
        elif nums[mid] < nums[hi]:
            hi = mid
        else:
            if nums[hi - 1] > nums[hi]:
                s = hi
                break
            hi -= 1
    if s is None:
        s = lo

    def bound(strict):
        l, r = 0, n
        while l < r:
            m = (l + r) // 2
            v = nums[(s + m) % n]
            if v < target or (strict and v == target):
                l = m + 1
            else:
                r = m
        return l

    a, b = bound(False), bound(True)
    if a == b:
        return -1
    if b - 1 >= n - s:
        return s + max(a, n - s) - n
    return s + a
